import os,json,subprocess
from pathlib import Path
projects={"iptvpn_bot":"/srv/projects/iptvpn-bot","telegram-robot-leads":"/srv/projects/telegram-robot-leads"}
out={"status":"AUDIT_ONLY","global_pm2_home":Path("/root/.pm2").is_dir(),"per_project":{},"live_apps":[],"saved_apps":[]}
try:
 proc=subprocess.run(["pm2","jlist"],env=dict(os.environ,PM2_HOME="/root/.pm2"),capture_output=True,text=True,timeout=15)
 apps=json.loads(proc.stdout) if proc.returncode==0 else []
 for a in apps:
  e=a.get("pm2_env",{})
  out["live_apps"].append({"name":a.get("name"),"pid":a.get("pid"),"status":e.get("status"),"cwd":e.get("pm_cwd"),"exec":e.get("pm_exec_path"),"interpreter":e.get("exec_interpreter"),"args_count":len(e.get("args",[]) or []),"env_key_count":len(e.get("env",{}) or {})})
except Exception as ex:out["pm2_error"]=type(ex).__name__
dump=Path("/root/.pm2/dump.pm2")
if dump.is_file():
 try:
  for a in json.loads(dump.read_text()):
   e=a.get("pm2_env",a)
   out["saved_apps"].append({"name":a.get("name"),"cwd":e.get("pm_cwd"),"exec":e.get("pm_exec_path")})
 except Exception:out["dump_unreadable"]=True
for name,base in projects.items():
 p=Path(base);home=p/".pm2"
 info={"project_root_real":p.is_dir() and not p.is_symlink(),"pm2_home_exists":home.exists() or home.is_symlink(),"python_venv":(p/".venv/bin/python").is_file(),"main_py":(p/"main.py").is_file(),"start_sh":(p/"start.sh").is_file(),"ecosystem":(p/"ecosystem.config.js").is_file()}
 if name=="telegram-robot-leads":
  info["session_count"]=len(list((p/"private").glob("*.session"))) if (p/"private").is_dir() else None
 out["per_project"][name]=info
service=subprocess.run(["systemctl","is-active","pm2-root"],capture_output=True,text=True,timeout=8)
out["pm2_root_service"]=service.stdout.strip()
print(json.dumps(out,sort_keys=True))
